code={'TTT':'F','TTC':'F','TTA':'L','TTG':'L','CTT':'L','CTC':'L','CTA':'L','CTG':'L','ATT':'I','ATC':'I','ATA':'I','ATG':'M','GTT':'V','GTC':'V','GTA':'V','GTG':'V','TCT':'S','TCC':'S','TCA':'S','TCG':'S','CCT':'P','CCC':'P','CCA':'P','CCG':'P','ACT':'T','ACC':'T','ACA':'T','ACG':'T','GCT':'A','GCC':'A','GCA':'A','GCG':'A','TAT':'Y','TAC':'Y','TAA':'*','TAG':'*','CAT':'H','CAC':'H','CAA':'Q','CAG':'Q','AAT':'N','AAC':'N','AAA':'K','AAG':'K','GAT':'D','GAC':'D','GAA':'E','GAG':'E','TGT':'C','TGC':'C','TGA':'*','TGG':'W','CGT':'R','CGC':'R','CGA':'R','CGG':'R','AGT':'S','AGC':'S','AGA':'R','AGG':'R','GGT':'G','GGC':'G','GGA':'G','GGG':'G'}
def prot_of(x,f):
    return ''.join(code[x[i:i+3]] for i in range(f,len(x)-2,3))
cases={'segA -f0':prot_of(rc(s[:1319]),0), 'segB +f2':prot_of(s[1319:],2)}
random.seed(31)
for nm,P in cases.items():
    P=P.replace('*','X')
    ac=Counter(P); N=len(P)
    pairs=Counter(P[i:i+2] for i in range(len(P)-1))
    # restrict to pairs with E>=5 for a valid chi2
    st=0.0; df=0
    for (a,b),o in pairs.items():
        E=ac[a]*ac[b]/N*(len(P)-1)
        if E>=5:
            st+=(o-E)**2/E; df+=1
    keys=list(ac); w=[ac[k]/N for k in keys]
    def gstat(PP):
        acx=Counter(PP); NN=len(PP)
        pr=Counter(PP[i:i+2] for i in range(NN-1))
        t=0.0
        for (a,b),o in pr.items():
            E=acx[a]*acx[b]/NN*(NN-1)
            if E>=5: t+=(o-E)**2/E
        return t
    nulls=sorted(gstat(''.join(random.choices(keys,weights=w,k=N))) for _ in range(300))
    pv=sum(1 for v in nulls if v>=st)/len(nulls)
    print(f"{nm}: aa-pair chi2={st:.1f} (df={df}); null median={nulls[150]:.1f} (df~{df}); P(obs>=x)={pv:.3f}")
